/**
 * Symmetrische Verschlüsselung: ROT13, Caesar und Vigenère (Stationen 5.1 und 5.2).
 * Verschlüsselt werden nur die Großbuchstaben A bis Z, alle anderen Zeichen
 * (z. B. Leerzeichen) bleiben, wie sie sind.
 * Suche (Strg + F) nach "TODO" und ergänze den Code.
 */
public class Symverschluesselung {

   /**
    * Verschiebt einen Großbuchstaben um rotationUm Stellen im Alphabet.
    * Nach Z geht es wieder bei A weiter.
    * Beispiele: rotiere('B', 3) liefert 'E', rotiere('Y', 3) liefert 'B'.
    */
   public char rotiere(char buchstabe, int rotationUm) {
      if (buchstabe < 'A' || buchstabe > 'Z') {   // ⓪ kein Großbuchstabe (z. B. Leerzeichen)?
         return buchstabe;                         //    dann unverändert zurückgeben
      }
      rotationUm = rotationUm % 26;               // ① 26 Schritte sind einmal ganz herum
      int code = (int) buchstabe + rotationUm;    // ② ASCII-Code + Verschiebung, z. B. 'Y' (89) + 3 = 92
      if (code > 90) {                            // ③ hinter 'Z' (Code 90) gelandet?
         code = code - 26;                        //    dann vorne weiterzählen: 92 - 26 = 66 ('B')
      }
      return (char) code;                         // ④ Zahl wieder als Zeichen zurückgeben
   }

   /**
    * ROT13: Jeder Buchstabe wird um 13 Stellen verschoben (Blatt 5.1, Aufgabe 2).
    * Beispiel: rot13("HALLO") liefert "UNYYB".
    */
   public String rot13(String klartext) {
      klartext = klartext.toUpperCase();                 // ① alles in Großbuchstaben
      String geheimtext = "";                            // ② der Geheimtext ist zuerst leer
      for (int i = 0; i < klartext.length(); i++) {      // ③ Zeichen für Zeichen (i = 0, 1, 2, ...)
         char zeichen = klartext.charAt(i);              // ④ das Zeichen an Position i holen
         geheimtext = geheimtext + rotiere(zeichen, 13); // ⑤ verschieben und hinten anhängen
      }
      return geheimtext;                                 // ⑥ fertigen Geheimtext zurückgeben
   }

   /**
    * TODO 1 (Blatt 5.2, Aufgabe 1): Caesar-Verschlüsselung mit beliebigem Schlüssel.
    * Beispiel: caesar("HALLO", 3) liefert "KDOOR".
    * Tipp: Vergleiche mit rot13. Was ist dort fest, was soll hier veränderbar sein?
    */
   public String caesar(String klartext, int schluessel) {
      klartext = klartext.toUpperCase();
      String geheimtext = "";
      for (int i = 0; i < klartext.length(); i++) {
         char zeichen = klartext.charAt(i);
         geheimtext = geheimtext + rotiere(zeichen, schluessel);   // statt 13 jetzt schluessel
      }
      return geheimtext;
   }

   /**
    * TODO 2 (Blatt 5.2, Aufgabe 1): Caesar-Entschlüsselung.
    * Beispiel: caesarEnt("KDOOR", 3) liefert "HALLO".
    * Tipp: rotiere kann nur vorwärts. Um 3 zurück ist dasselbe wie um 23 vor.
    */
   public String caesarEnt(String geheimtext, int schluessel) {
      schluessel = schluessel % 26;
      return caesar(geheimtext, 26 - schluessel);   // um k zurück = um 26 - k vor
      // Ebenfalls richtig: die Schleife aus caesar kopieren und rotiere(zeichen, 26 - schluessel) aufrufen.
   }

   // ---------- Selbst bauen (Website): Vigenère ----------

   /**
    * Wie weit verschiebt ein Schlüsselbuchstabe? 'A' = 0, 'B' = 1, ..., 'Z' = 25
    */
   public int verschiebung(char schluesselbuchstabe) {
      return (int) schluesselbuchstabe - 65;
   }

   /**
    * TODO 3: Vigenère-Verschlüsselung. Das Zeichen an Position i wird um den
    * Schlüsselbuchstaben an Position i % schluessel.length() verschoben
    * (so wiederholt sich das Schlüsselwort: ELFELFELF...).
    * Beispiel: vigenere("KAFFEE", "ELF") liefert "OLKJPJ".
    */
   public String vigenere(String klartext, String schluessel) {
      klartext = klartext.toUpperCase();
      schluessel = schluessel.toUpperCase();
      String geheimtext = "";
      for (int i = 0; i < klartext.length(); i++) {
         char s = schluessel.charAt(i % schluessel.length());   // Schlüsselbuchstabe für Position i
         geheimtext = geheimtext + rotiere(klartext.charAt(i), verschiebung(s));
      }
      return geheimtext;
   }

   /**
    * TODO 4: Vigenère-Entschlüsselung.
    * Beispiel: vigenereEnt("OLKJPJ", "ELF") liefert "KAFFEE".
    */
   public String vigenereEnt(String geheimtext, String schluessel) {
      geheimtext = geheimtext.toUpperCase();
      schluessel = schluessel.toUpperCase();
      String klartext = "";
      for (int i = 0; i < geheimtext.length(); i++) {
         char s = schluessel.charAt(i % schluessel.length());
         klartext = klartext + rotiere(geheimtext.charAt(i), 26 - verschiebung(s));
      }
      return klartext;
   }
}

