public class SymverschluesselungTest {

   @Test
   public void rot13Beispiel() {
      Symverschluesselung sv = new Symverschluesselung();
      Assertions.assertEquals("UNYYB", sv.rot13("HALLO"), "rot13(\"HALLO\") muss UNYYB liefern.");
   }

   @Test
   public void caesarEinfach() {
      Symverschluesselung sv = new Symverschluesselung();
      Assertions.assertEquals("KDOOR", sv.caesar("HALLO", 3), "TODO 1: caesar(\"HALLO\", 3) muss KDOOR liefern.");
   }

   @Test
   public void caesarUeberZ() {
      Symverschluesselung sv = new Symverschluesselung();
      Assertions.assertEquals("ABC", sv.caesar("XYZ", 3), "TODO 1: caesar(\"XYZ\", 3) muss ABC liefern (nach Z geht es bei A weiter).");
   }

   @Test
   public void caesarKleinUndLeer() {
      Symverschluesselung sv = new Symverschluesselung();
      Assertions.assertEquals("IBMMP XFMU", sv.caesar("Hallo Welt", 1), "TODO 1: caesar(\"Hallo Welt\", 1) muss IBMMP XFMU liefern.");
   }

   @Test
   public void caesarEntEinfach() {
      Symverschluesselung sv = new Symverschluesselung();
      Assertions.assertEquals("HALLO", sv.caesarEnt("KDOOR", 3), "TODO 2: caesarEnt(\"KDOOR\", 3) muss HALLO liefern.");
   }

   @Test
   public void caesarHinUndZurueck() {
      Symverschluesselung sv = new Symverschluesselung();
      for (int k = 0; k < 30; k++) {
         Assertions.assertEquals("ZEBRA", sv.caesarEnt(sv.caesar("ZEBRA", k), k), "TODO 2: Mit Schlüssel " + k + " kommt beim Entschlüsseln nicht wieder ZEBRA heraus.");
      }
   }

   @Test
   public void vigenereBeispiel() {
      Symverschluesselung sv = new Symverschluesselung();
      Assertions.assertEquals("OLKJPJ", sv.vigenere("KAFFEE", "ELF"), "TODO 3: vigenere(\"KAFFEE\", \"ELF\") muss OLKJPJ liefern.");
   }

   @Test
   public void vigenereEntBeispiel() {
      Symverschluesselung sv = new Symverschluesselung();
      Assertions.assertEquals("KAFFEE", sv.vigenereEnt("OLKJPJ", "ELF"), "TODO 4: vigenereEnt(\"OLKJPJ\", \"ELF\") muss KAFFEE liefern.");
   }
}
